#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_append_n_enough_space_no_resize(void) {
    // Setup: create buffer with enough space for append
    // Initial data: "foo", buffer size: 16 (enough for "foo" + 3 chars + null)
    buffer_t *buf = buffer_new_with_size(16);
    TEST_ASSERT_NOT_NULL(buf);
    strcpy(buf->data, "foo");

    // Confirm initial state
    helper_assert_buffer_string_equals(buf, "foo");
    helper_assert_buffer_length(buf, 3);
    helper_assert_buffer_size(buf, 16);

    // Prepare string to append
    const char *to_append = "barbaz";
    size_t append_len = 3; // append only "bar"

    // Calculate needed: prev = 3, needed = 3+3=6, self->len=16 > 6, so no resize
    int ret = buffer_append_n(buf, to_append, append_len);

    // Assert return value
    TEST_ASSERT_EQUAL_INT(0, ret);

    // Assert buffer content: should be "foobar"
    helper_assert_buffer_string_equals(buf, "foobar");
    helper_assert_buffer_length(buf, 6);
    helper_assert_buffer_size(buf, 16);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_enough_space_no_resize);
    return UNITY_END();
}


